bug_report:
verify_flow_info ICE with nested functions and non-local goto/labels
When I compile this C code with an i686-unknown-linux-gnu native mainline compiler, I get an ICE.

int
main ()
{
  int f1 ()
  {
    __label__ lab;

    int f2 ()
    {
      goto lab;
    }

    return f2 () + f2 ();

  lab:
    return 2;
  }

  if (f1 () != 2)
    abort ();
  exit (0);
}

